## Interactive CodeMirror Editor

<div id="editor-target" style="border: 1px solid #cbd5e1; border-radius: 6px; margin: 10px 0;"></div>
<div style="margin-bottom: 1rem;">
  <button id="get-btn" style="padding: 6px 12px; cursor: pointer; margin-right: 6px;">Get Content</button>
  <button id="set-btn" style="padding: 6px 12px; cursor: pointer;">Set Content</button>
</div>

<script type="module">
  import { basicSetup } from "https://esm.sh/codemirror@6.0.1";
  import { EditorView } from "https://esm.sh/@codemirror/view@6.28.0";

  const view = new EditorView({
    doc: "Start document - native Quarto HTML block.",
    parent: document.querySelector("#editor-target"),
    extensions: [
      basicSetup,
      EditorView.updateListener.of(update => {
        if (update.docChanged) {
          console.log("Document updated dynamically.");
        }
      })
    ]
  });

  document.querySelector("#get-btn").addEventListener("click", () => {
    alert("Current Text:\n\n" + view.state.doc.toString());
  });

  document.querySelector("#set-btn").addEventListener("click", () => {
    view.dispatch({
      changes: {
        from: 0,
        to: view.state.doc.length,
        insert: "# Programmatic Update\n\nContent replaced via view.dispatch()."
      }
    });
  });
</script>
